package in.recallradar;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/incidents") class IncidentController {private final IncidentService service;private final TenantService tenants;IncidentController(IncidentService s,TenantService t){service=s;tenants=t;}private Membership m(Authentication a,String org){return tenants.membership(UUID.fromString(a.getName()),org);}@GetMapping List<IncidentResponse> list(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org){return service.list(m(a,org));}@PostMapping @ResponseStatus(HttpStatus.CREATED) IncidentResponse create(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@Valid @RequestBody IncidentCreateRequest r){return service.create(m(a,org),r);}@PutMapping("/{id}/status") IncidentResponse status(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@PathVariable UUID id,@Valid @RequestBody IncidentStatusRequest r){return service.status(m(a,org),id,r);}@PostMapping("/{id}/quarantines/{quarantineId}/release") IncidentResponse release(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@PathVariable UUID id,@PathVariable UUID quarantineId){return service.release(m(a,org),id,quarantineId);}@PostMapping("/{id}/actions") @ResponseStatus(HttpStatus.CREATED) IncidentResponse action(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@PathVariable UUID id,@Valid @RequestBody CorrectiveActionRequest r){return service.addAction(m(a,org),id,r);}@PostMapping("/{id}/actions/{actionId}/complete") IncidentResponse complete(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@PathVariable UUID id,@PathVariable UUID actionId){return service.completeAction(m(a,org),id,actionId);}}
